<?php
namespace SenderSuite;

/** Opt-in, one-contact cloud SMS outbox. Never retries a possibly submitted POST. */
final class SmsOutbox {
    const HOOK='sender_suite_sms_outbox';
    private $db;private $config;private $records;
    public function __construct(Database $db,Config $config,callable $clock=null){$this->db=$db;$this->config=$config;$this->records=new Records($db,$clock);}
    public static function enabled(){return defined('SENDER_SUITE_ENABLE_SMS_OUTBOX')&&SENDER_SUITE_ENABLE_SMS_OUTBOX===true;}
    public static function definitions(){return array_merge(ScheduledSms::definitions(),array('/send/?'=>array('POST'),'/send/messages/(?P<message_id>-?[0-9]+)'=>array('GET'),'/send/messages/(?P<message_id>-?[0-9]+)/cancel'=>array('POST')));}
    public static function schedule(){if(!self::enabled()){return false;}if(wp_next_scheduled(self::HOOK)!==false){return true;}return wp_schedule_event(time()+1,'sender_suite_five_minutes',self::HOOK,array(),true)===true;}
    public static function deactivate(){wp_clear_scheduled_hook(self::HOOK);}
    public static function boot($file){if(!self::enabled()){return;}add_action('init',array(self::class,'schedule'));add_action(self::HOOK,array(self::class,'tick'));register_deactivation_hook($file,array(self::class,'deactivate'));}
    public static function tick(){if(!self::enabled()){return;}try{$c=AuthRoutes::context();if($c['config']->ready()){(new self($c['db'],$c['config']))->process();}}catch(\Throwable $e){/* Durable claim remains, no secret/body logging and no automatic resubmission. */}}
    private function table($t){return Schema::identifier($this->db->schema()->table($t));}
    private function meta($raw){try{$d=json_decode($raw??'',true,16,JSON_THROW_ON_ERROR);}catch(\Throwable $e){throw new AuthFailure(503,'Outbox metadata needs repair.');}if(!is_array($d)||($d['native_sms_outbox']??null)!==1||!is_int($d['owner_id']??null)||$d['owner_id']<1||!is_int($d['gateway_id']??null)||$d['gateway_id']<1||!is_string($d['phone']??null)||!preg_match('/^\+[1-9][0-9]{7,14}$/D',$d['phone'])||!is_string($d['request_sha256']??null)||!preg_match('/^[a-f0-9]{64}$/D',$d['request_sha256'])||!is_string($d['sender_version']??null)||!preg_match('/^[a-f0-9]{64}$/D',$d['sender_version'])){throw new AuthFailure(503,'Outbox metadata needs repair.');}if(isset($d['schedule_at'])){try{if(!is_string($d['schedule_at'])||Calendar::date($d['schedule_at'],'schedule_at')!==$d['schedule_at']){throw new \RuntimeException();}}catch(\Throwable $e){throw new AuthFailure(503,'Outbox schedule metadata needs repair.');}}return $d;}
    private function contact($id,$phone=null){
        $rows=$this->db->rows('SELECT id,phone_number,has_consented,consent_status,is_opted_out,is_undeliverable,messages_sent FROM '.$this->table('contacts').' WHERE id=%d',array($id));if(!$rows){throw new AuthFailure(404,'Contact not found');}$c=$this->db->decode('contacts',$rows[0]);$n=NumberFilter::classify($c['phone_number']);
        if(!$c['has_consented']||$c['consent_status']!=='opted_in'||$c['is_opted_out']||$c['is_undeliverable']||!$n['sendable']||$c['phone_number']!==$n['normalized']||$this->db->one('suppression_entries',array('phone_number'=>$c['phone_number']))){throw new AuthFailure(400,'Contact is not explicitly opted in and sendable.');}
        if($phone!==null&&$n['normalized']!==$phone){throw new AuthFailure(409,'Recipient number changed after enqueue.');}if($c['messages_sent']<0||$c['messages_sent']>=2147483647){throw new AuthFailure(503,'Contact message counter is exhausted.');}return array($c,$n['normalized']);
    }
    private function sender($id){$rows=$this->db->rows('SELECT id,is_enabled,provider,mode,daily_limit,base_url,username,password_encrypted,device_id,sim_number FROM '.$this->table('gateway_settings').' WHERE id=%d',array($id));$r=$rows?$this->db->decode('gateway_settings',$rows[0]):null;if(!$r){throw new AuthFailure(404,'Sender phone not found');}if($r['daily_limit']!==0){throw new AuthFailure(503,'Daily-limited senders require the remaining budget worker; this outbox will not ignore the limit.');}if(!$r['is_enabled']||$r['provider']!=='smsgate'||$r['mode']!=='cloud'||!in_array($r['sim_number'],array(1,2),true)){throw new AuthFailure(503,'Sender is not an enabled cloud SMS-Gate phone.');}
        try{$password=$this->config->openRuntimeSecret($this->db->schema()->table('gateway_settings').'/'.$r['id'].'/password',$r['password_encrypted']);}catch(\Throwable $e){throw new AuthFailure(503,'Sender credentials need replacement.');}
        if($password===''||!is_string($r['username'])||$r['username']===''||strpos($r['username'],':')!==false){throw new AuthFailure(503,'Sender credentials need repair.');}
        $c=array('base_url'=>SmsGate::base($r['base_url']),'username'=>$r['username'],'password'=>$password,'device_id'=>$r['device_id'],'sim_number'=>$r['sim_number']);$c['_native_sender_version']=hash('sha256',json_encode(array($r['base_url'],$r['username'],$r['password_encrypted'],$r['device_id'],$r['sim_number']),JSON_THROW_ON_ERROR));return $c;}
    private static function digest($contact,$gateway,$body,$schedule=null){$data=array($contact,$gateway,$body);if($schedule!==null){$data[]=$schedule;}return hash('sha256',json_encode($data,JSON_THROW_ON_ERROR));}
    private function due(array $m,array $meta){return $meta['schedule_at']??$m['created_at'];}
    private function publicMessage(array $m){$out=array('success'=>true,'message_id'=>$m['id'],'status'=>$m['status'],'queued'=>$m['status']==='queued','provider_message_id'=>$m['provider_message_id'],'sent_at'=>Records::iso($m['sent_at']),'delivered_at'=>Records::iso($m['delivered_at']),'failed_at'=>Records::iso($m['failed_at']),'needs_review'=>$m['status']==='unknown');$meta=$this->meta($m['provider_response']);if(isset($meta['schedule_at'])){$linked=ScheduledSms::linked($this->db,$m['id']);$out['scheduled_id']=$linked?$linked['id']:null;$out['schedule_at']=Records::iso($meta['schedule_at']);}return $out;}
    private function message($id){$rows=$this->db->rows('SELECT id,contact_id,conversation_id,created_at,status,provider_message_id,sent_at,delivered_at,failed_at,CASE WHEN OCTET_LENGTH(provider_response)<=8192 THEN provider_response ELSE NULL END AS provider_response,idempotency_key,retry_count,retry_at FROM '.$this->table('messages').' WHERE id=%d AND provider=%s AND direction=%s AND channel=%s',array($id,'smsgate','outgoing','sms'));if(!$rows||strpos($rows[0]['idempotency_key'],'native-sms:')!==0){throw new AuthFailure(404,'Outbox message not found');}if(strlen($rows[0]['provider_response']??'')>8192){throw new AuthFailure(503,'Outbox metadata needs repair.');}return $this->db->decode('messages',$rows[0]);}
    public function read($id,array $user){$m=$this->message($id);$meta=$this->meta($m['provider_response']);if($user['role']!=='admin'&&$meta['owner_id']!==$user['id']){throw new AuthFailure(404,'Outbox message not found');}return $this->publicMessage($m);}
    /** Caller owns transaction. Only persists; transport is never invoked here. */
    public function enqueue($contactId,$gatewayId,$body,$key,array $user,$scheduleAt=null){
        if(!self::enabled()){throw new AuthFailure(503,'The SMS outbox is disabled pending native qualification.');}if(($user['role']??'')!=='admin'){throw new AuthFailure(403,'Application administrator role required.');}
        if(!is_string($key)||!preg_match('/^[A-Za-z0-9._:-]{8,128}$/D',$key)){throw new ValidationFailure('Supply an 8–128 character Idempotency-Key header');}
        if(!is_string($body)||$body===''||strlen($body)>6400||preg_match('//u',$body)!==1||strpos($body,"\0")!==false||Compat::length($body)>1600){throw new ValidationFailure('Supply final SMS text of 1–1600 characters');}if(preg_match('/\{\{?|\}\}?/',$body)){throw new AuthFailure(503,'Template rendering for this send path is not enabled; supply final text without placeholders.');}
        list($chars,$segments)=Templating::segments($body);if($segments>5){throw new AuthFailure(400,'SMS exceeds the five-segment safety limit.');}
        $schedule=$scheduleAt!==null?Calendar::date($scheduleAt,'schedule_at'):null;
        $identity='native-sms:'.hash('sha256',$user['id'].':'.$key);$digest=self::digest($contactId,$gatewayId,$body,$schedule);$oldRows=$this->db->rows('SELECT id FROM '.$this->table('messages').' WHERE idempotency_key=%s LIMIT 1',array($identity));$old=$oldRows?$this->message((int)$oldRows[0]['id']):null;if($old){$meta=$this->meta($old['provider_response']);if(!hash_equals($meta['request_sha256'],$digest)){throw new AuthFailure(409,'Idempotency key was already used for different message content.');}return $this->publicMessage($old);}
        if($schedule!==null&&($schedule<=$this->records->now()||$schedule>(new \DateTimeImmutable($this->records->now(),new \DateTimeZone('UTC')))->modify('+365 days')->format('Y-m-d H:i:s.u'))){throw new AuthFailure(400,'schedule_at must be in the future and no more than 365 days away.');}
        list($c,$phone)=$this->contact($contactId);$sender=$this->sender($gatewayId);
        $conversations=$this->db->select('conversations',array('contact_id'=>$contactId,'channel'=>'sms'),2);if(count($conversations)>1){throw new AuthFailure(409,'SMS conversation is ambiguous.');}$conv=$conversations?$conversations[0]:$this->records->create('conversations',array('contact_id'=>$contactId,'channel'=>'sms'));
        $meta=array('native_sms_outbox'=>1,'owner_id'=>$user['id'],'gateway_id'=>$gatewayId,'sender_version'=>$sender['_native_sender_version'],'phone'=>$phone,'request_sha256'=>$digest);if($schedule!==null){$meta['schedule_at']=$schedule;}
        $m=$this->records->create('messages',array('contact_id'=>$contactId,'conversation_id'=>$conv['id'],'direction'=>'outgoing','channel'=>'sms','body'=>$body,'char_count'=>$chars,'segment_count'=>$segments,'status'=>'queued','retry_at'=>$schedule,'provider'=>'smsgate','idempotency_key'=>$identity,'provider_response'=>json_encode($meta,JSON_THROW_ON_ERROR)));if($schedule!==null){$this->records->create('scheduled_messages',array('contact_id'=>$contactId,'phone_number'=>$phone,'body'=>$body,'channel'=>'sms','schedule_at'=>$schedule,'sim_number'=>$sender['sim_number'],'message_id'=>$m['id']));}return $this->publicMessage($m);
    }
    public function cancel($id,array $user){if(($user['role']??'')!=='admin'){throw new AuthFailure(403,'Application administrator role required.');}$m=$this->message($id);$this->meta($m['provider_response']);if($m['status']==='cancelled'&&$m['retry_count']===0&&$m['provider_message_id']===null){return $this->publicMessage($m);}if($m['status']!=='queued'||$m['retry_count']!==0||$m['provider_message_id']!==null){throw new AuthFailure(400,'Only an unclaimed queued SMS may be cancelled.');}$patch=array('status'=>'cancelled','retry_at'=>null);$this->settle($m,$patch);return $this->publicMessage(array_replace($m,$patch));}
    private function settle(array $m,array $patch){if($this->db->update('messages',$patch,array('id'=>$m['id'],'status'=>$m['status'],'retry_count'=>$m['retry_count'],'retry_at'=>$m['retry_at'],'provider_message_id'=>$m['provider_message_id']))!==1){throw new AuthFailure(409,'Outbox message changed. No resubmission is permitted.');}ScheduledSms::sync($this->db,$this->records,$m,$patch);}
    private function claim($id){return $this->db->transaction(function()use($id){
        $m=$this->message($id);if($m['status']!=='queued'||$m['retry_count']!==0){return null;}
        try{$meta=$this->meta($m['provider_response']);$due=$this->due($m,$meta);if($due>$this->records->now()){return null;}if((new \DateTimeImmutable($due,new \DateTimeZone('UTC')))->modify('+1 hour')->format('Y-m-d H:i:s.u')<=$this->records->now()){$this->settle($m,array('status'=>'failed','failed_at'=>$this->records->now(),'last_error'=>'Queued SMS expired before submission.'));return null;}
            if(isset($meta['schedule_at'])){$linked=ScheduledSms::linked($this->db,$m['id']);if(!$linked||$linked['status']!=='pending'||$linked['schedule_at']!==$meta['schedule_at']){throw new AuthFailure(409,'Scheduled linkage changed.');}}
            list($c,$phone)=$this->contact($m['contact_id'],$meta['phone']);$credentials=$this->sender($meta['gateway_id']);if(($meta['sender_version']??null)!==$credentials['_native_sender_version']){throw new AuthFailure(409,'Sender configuration changed after enqueue.');}}catch(AuthFailure $e){$this->settle($m,array('status'=>'failed','failed_at'=>$this->records->now(),'last_error'=>'Delivery admission failed. No request submitted.'));return null;}
        $raw=$this->db->rows('SELECT body FROM '.$this->table('messages').' WHERE id=%d AND OCTET_LENGTH(body)<=6400',array($m['id']));if(!$raw){$this->settle($m,array('status'=>'failed','failed_at'=>$this->records->now(),'last_error'=>'Stored SMS exceeds the delivery limit.'));return null;}
        $body=$raw[0]['body'];if($body===''||Compat::length($body)>1600||Templating::segments($body)[1]>5||!hash_equals($meta['request_sha256'],self::digest($m['contact_id'],$meta['gateway_id'],$body,$meta['schedule_at']??null))){$this->settle($m,array('status'=>'failed','failed_at'=>$this->records->now(),'last_error'=>'Stored SMS is invalid.'));return null;}
        $patch=array('status'=>'sending','retry_count'=>1,'retry_at'=>(new \DateTimeImmutable($this->records->now(),new \DateTimeZone('UTC')))->modify('+2 minutes')->format('Y-m-d H:i:s.u'));$this->settle($m,$patch);return array('message'=>array_replace($m,$patch),'credentials'=>$credentials,'body'=>$body);
    });}
    private function finish(array $claim,array $result){return $this->db->transaction(function()use($claim,$result){
        $m=$claim['message'];$now=$this->records->now();$outcome=$result['outcome'];$patch=array('status'=>$outcome==='rejected'?'failed':'unknown','retry_at'=>null,'last_error'=>$outcome==='rejected'?'Gateway rejected the request.':'Submission outcome unknown. Manual review required; never automatically resend.');if($outcome==='rejected'){$patch['failed_at']=$now;}
        if($outcome==='accepted'){
            $patch=array('status'=>$result['status']==='sent'?'sent':'sending','provider_message_id'=>$result['provider_message_id'],'retry_at'=>(new \DateTimeImmutable($now,new \DateTimeZone('UTC')))->modify('+5 minutes')->format('Y-m-d H:i:s.u'),'last_error'=>null,'sent_at'=>$result['status']==='sent'?$now:null);
            // A colliding provider identity cannot be safely attributed to this receipt stream.
            $duplicates=$this->db->rows('SELECT id FROM '.$this->table('messages').' WHERE provider=%s AND provider_message_id=%s AND id<>%d LIMIT 1',array('smsgate',$result['provider_message_id'],$m['id']));if($duplicates){throw new AuthFailure(409,'Provider reused a message identity. Keep the claim for manual review.');}
        }
        $this->settle($m,$patch);
        if($outcome==='accepted'){
            if($this->db->execute('UPDATE '.$this->table('contacts').' SET messages_sent=messages_sent+1,last_contacted_at=%s,updated_at=%s WHERE id=%d AND messages_sent<2147483647',array($now,$now,$m['contact_id']))!==1){throw new AuthFailure(409,'Contact counter changed. Keep the submission for review.');}
            if($this->db->execute('UPDATE '.$this->table('conversations').' SET message_count=message_count+1,last_message_at=%s,last_message_preview=%s,updated_at=%s WHERE id=%d AND message_count<2147483647',array($now,implode('',array_map(array(Compat::class,'chr'),array_slice(Compat::points($claim['body']),0,200))),$now,$m['conversation_id']))!==1){throw new AuthFailure(409,'Conversation counter changed. Keep the submission for review.');}
            if(in_array($result['status'],array('delivered','failed','cancelled'),true)){(new SmsReceipts($this->db,$this->config))->reconcile($result['provider_message_id'],$result['status'],$now);}
        }
    });}
    private function pollOne(){
        $rows=$this->db->rows('SELECT id FROM '.$this->table('messages')." WHERE idempotency_key LIKE 'native-sms:%%' AND provider='smsgate' AND direction='outgoing' AND channel='sms' AND provider_message_id IS NOT NULL AND status IN ('sending','sent') AND (retry_at IS NULL OR retry_at<=%s) ORDER BY retry_at ASC,id ASC LIMIT 1",array($this->records->now()));if(!$rows){return array('processed'=>0);}$m=$this->message((int)$rows[0]['id']);
        $meta=$this->meta($m['provider_response']);if((new \DateTimeImmutable($this->due($m,$meta),new \DateTimeZone('UTC')))->modify('+24 hours')->format('Y-m-d H:i:s.u')<=$this->records->now()){$this->db->transaction(function()use($m){$this->settle($m,array('status'=>'unknown','retry_at'=>null,'last_error'=>'Delivery observation window expired. Manual review required.'));});return array('polled'=>0,'needs_review'=>true);}$meta=$this->meta($m['provider_response']);
        try{$c=$this->sender($meta['gateway_id']);if(($meta['sender_version']??null)!==$c['_native_sender_version']){throw new AuthFailure(409,'Sender changed.');}$result=SmsGate::poll($c,$m['provider_message_id']);}catch(\Throwable $e){$result=array('outcome'=>'unknown');}
        $this->db->transaction(function()use($m,$result){
            if(($result['outcome']??null)==='observed'&&in_array($result['status'],array('sent','delivered','failed','cancelled'),true)){(new SmsReceipts($this->db,$this->config))->reconcile($m['provider_message_id'],$result['status'],$this->records->now());}
            $current=$this->message($m['id']);if(in_array($current['status'],array('sending','sent'),true)){$this->settle($current,array('retry_at'=>(new \DateTimeImmutable($this->records->now(),new \DateTimeZone('UTC')))->modify('+5 minutes')->format('Y-m-d H:i:s.u')));}
        });return array('polled'=>1,'outcome'=>$result['outcome']);
    }
    /** One serialized worker, one POST per queued row, committed claim before all network effects. */
    public function process(){
        if(!self::enabled()){return array('disabled'=>true);}$this->db->requireOutsideTransaction();$name='ss_sms_'.substr(hash('sha256',$this->db->schema()->table('messages')),0,50);$lock=$this->db->rows('SELECT GET_LOCK(%s,0) AS acquired',array($name));if((int)($lock[0]['acquired']??0)!==1){return array('busy'=>true);}
        try{
            // A lost claim is never returned to queued, even if it died before its POST.
            $this->db->transaction(function(){
                $lost=$this->db->rows('SELECT id FROM '.$this->table('messages')." WHERE idempotency_key LIKE 'native-sms:%%' AND provider='smsgate' AND status='sending' AND provider_message_id IS NULL AND retry_at<=%s ORDER BY id ASC LIMIT 100",array($this->records->now()));foreach($lost as $row){$m=$this->message((int)$row['id']);if($m['status']==='sending'&&$m['provider_message_id']===null&&$m['retry_at']!==null&&$m['retry_at']<=$this->records->now()){$this->settle($m,array('status'=>'unknown','retry_at'=>null,'last_error'=>'Worker interrupted; submission may have happened. Manual review required.'));}}
            });
            $ids=$this->db->rows('SELECT id FROM '.$this->table('messages')." WHERE idempotency_key LIKE 'native-sms:%%' AND provider='smsgate' AND channel='sms' AND direction='outgoing' AND status='queued' AND retry_count=0 AND (retry_at IS NULL OR retry_at<=%s) ORDER BY id ASC LIMIT 1",array($this->records->now()));if(!$ids){return $this->pollOne();}$claim=$this->claim((int)$ids[0]['id']);if(!$claim){return array('processed'=>1,'submitted'=>false);}
            try{$c=$claim['credentials'];$result=SmsGate::send($c,$this->meta($claim['message']['provider_response'])['phone'],$claim['body'],$c['sim_number'],$c['device_id']);}catch(\Throwable $e){$result=array('outcome'=>'unknown');}
            $this->finish($claim,$result);return array('processed'=>1,'outcome'=>$result['outcome'],'poll'=>$this->pollOne());
        }finally{$this->db->rows('SELECT RELEASE_LOCK(%s) AS released',array($name));}
    }
    public static function handle($request,array $c,array $user,&$status){
        $path=trim(substr($request->get_route(),strlen('/sender-suite/v1/')),'/');$s=new self($c['db'],$c['config']);if($path==='send/scheduled'||strpos($path,'send/scheduled/')===0){return ScheduledSms::handle($request,$c,$user);}if($request->get_method()==='POST'&&preg_match('~^send/messages/(-?[0-9]+)/cancel$~D',$path,$m)){return $s->cancel(DataRoutes::integer($m[1],'message_id',1),$user);}if($request->get_method()==='GET'&&preg_match('~^send/messages/(-?[0-9]+)$~D',$path,$m)){return $s->read(DataRoutes::integer($m[1],'message_id',1),$user);}
        if($path!=='send'||$request->get_method()!=='POST'){throw new AuthFailure(404,'Not found');}if(!self::enabled()){throw new AuthFailure(503,'The SMS outbox is disabled pending native qualification.');}if($user['role']!=='admin'){throw new AuthFailure(403,'Application administrator role required.');}
        $q=$request->get_query_params();unset($q['rest_route']);if($q){throw new ValidationFailure('This queued send path accepts JSON only.');}if(strlen($request->get_body())>8192){throw new AuthFailure(413,'Send request is too large.');}$body=DataRoutes::body($request);if(!is_object($body)){throw new ValidationFailure('Supply a JSON object');}foreach($body as $key=>$v){if(in_array($key,array('list_id','phone_number'),true)){throw new AuthFailure(503,'Bulk and raw-number sends are not implemented in this outbox.');}if(!in_array($key,array('contact_id','gateway_setting_id','body','schedule_at'),true)){throw new ValidationFailure('Unknown queued send field',$key);}}
        $d=get_object_vars($body);$status=202;return $s->enqueue(DataRoutes::integer($d['contact_id']??null,'contact_id',1),DataRoutes::integer($d['gateway_setting_id']??null,'gateway_setting_id',1),DataRoutes::text($d,'body',null,1,1600),$request->get_header('idempotency-key'),$user,$d['schedule_at']??null);
    }
}
